   278	\begin{lemma}[Consistency from closeness with one projective family; Fact 4.14 in \cite{Natarajan2018NEEXP}]\label{fact:agreement-one-sided}
   279		% Status: the statement is final; no Lean declaration exists yet for the full disjunctive form, so this node carries no formalization marker.
   280		\uses{def:consistency, def:povm-distance}
   281		Let $\{A^x_a\}$ and $\{B^x_a\}$ be POVMs. If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ and either $\{A^x_a\}$ or $\{B^x_a\}$ is a projective measurement, then $A^x_a \ot \Id_B \simeq_{\delta^{1/2}} \Id_A \ot B^x_a$.
   282	\end{lemma}
   283	\begin{proof}
   284		\uses{lem:distance-projective-left-square-root}
   285		Stated in the source without proof; it is Fact 4.14 of \cite{Natarajan2018NEEXP}. Write the off-diagonal mass $\sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi}$ as an inner product involving $(A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi}$, using projectivity of one of the two families, and apply the Cauchy--Schwarz inequality; this route costs a square root in the error. Only the branch in which $\{A^x_a\}$ is the projective family is available, as Lemma~\ref{lem:agreement-projective-left}; the branch in which only $\{B^x_a\}$ is projective is still open.
   286	\end{proof}
