   288	\begin{lemma}[Left-projective branch of Lemma~\ref{fact:agreement-one-sided}]\label{lem:agreement-projective-left}
   289		\lean{MIPStarRE.QPBT.consistencyDefect_le_sqrt_of_projective_left}
   290		\leanok
   291		\uses{def:consistency, def:povm-distance}
   292		This entry states only the branch of Lemma~\ref{fact:agreement-one-sided} in which the left family is the projective one; it is not the full disjunctive statement of the source. Let $\mu$ be a probability distribution on $\mathcal X$, let $\ket{\psi}$ be a unit vector, and let $\{A^x_a\}$ be a projective measurement for every $x$. Then
   293		\[
   294			\E_x \sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi}
   295			\leq \sqrt{2\, \E_x \sum_a \bigl\lVert (A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi} \bigr\rVert^2}\,;
   296		\]
   297		in particular, if $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$, then $A^x_a \ot \Id_B \simeq_{(2\delta)^{1/2}} \Id_A \ot B^x_a$.
   298	\end{lemma}
   299	\begin{proof}
   300		\leanok
   301		\uses{lem:distance-projective-left-square-root, lem:distance-averaged-square-root}
   302		Apply the pointwise estimate of Lemma~\ref{lem:distance-projective-left-square-root} at each question $x$, then average over $x$ with Lemma~\ref{lem:distance-averaged-square-root}.
   303	\end{proof}
   304	
   305	\begin{lemma}[Fact 4.20 in \cite{Natarajan2018NEEXP}]\label{fact:add-a-proj}
   306		\lean{MIPStarRE.QPBT.opFamilyDistSq_mul_left_le}
   307		\leanok
   308		\uses{def:povm-distance}
   309		Let $\mathcal A, \mathcal B, \mathcal C$ be finite sets, and let $\mu$ be a distribution over question pairs $(x,y)$. Let $\{A^x_{a,\,b}\}$ and $\{B^x_{a,\,b}\}$ be operators whose outcomes range over the product set $\mathcal A \times \mathcal B$. Suppose a set of operators $\{C^y_{a,\,c}\}$, whose outcomes range over the product set $\mathcal A \times \mathcal C$, satisfies the condition $\sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \le \Id$ for all $a$ and all $y$. If $A^x_{a,\,b} \approx_\delta B^x_{a,\,b}$ on average over $x$ sampled from the corresponding marginal of the distribution $\mu$, then $C^y_{a,\,c} A^x_{a,\,b} \approx_\delta C^y_{a,\,c} B^x_{a,\,b}$ on average over $(x,y)$ sampled from $\mu$.
   310	\end{lemma}
   311	\begin{proof}
   312		\leanok
   313		\uses{lem:distance-sum-contraction}
   314		Fix questions $x, y$ and answers $a \in \mathcal A$, $b \in \mathcal B$. Then
   315		\begin{align*}
   316			\sum_c \bigl\lVert (C^y_{a,\,c} A^x_{a,\,b} - C^y_{a,\,c} B^x_{a,\,b})\, \ket{\psi} \bigr\rVert^2
   317			&= \bra{\psi} (A^x_{a,\,b} - B^x_{a,\,b})^\dagger \Bigl( \sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \Bigr) (A^x_{a,\,b} - B^x_{a,\,b}) \ket{\psi}\\
   318			&\le \bigl\lVert (A^x_{a,\,b} - B^x_{a,\,b})\, \ket{\psi} \bigr\rVert^2\,,
   319		\end{align*}
   320		where the inequality uses the assumption $\sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \le \Id$. Summing over $a, b$ and averaging over $(x,y) \sim \mu$ yields the conclusion.
   321	\end{proof}
   322	
   323	\begin{lemma}[Multiplying by function-indexed operators]\label{fact:add-a-proj2}
   324		\lean{MIPStarRE.QPBT.opFamilyDistSq_mul_funIndexed_le}
   325		\leanok
   326		\uses{def:povm-distance}
   327		Let $\mathcal X, \mathcal A$ be finite sets, and let $\mathcal G$ be a set of functions $g \colon \mathcal X \to \mathcal A$. Let $\{A^x_a\}$ and $\{B^x_a\}$ be POVMs indexed by $\mathcal X$ with outcomes in $\mathcal A$. Let $\{S^x_g\}_{x \in \mathcal X,\, g \in \mathcal G}$ be a set of operators such that for all $x \in \mathcal X$, $\sum_g (S^x_g)^\dagger S^x_g \le \Id$. If $A^x_a \approx_\delta B^x_a$ on average over $x$, then $S^x_g A^x_{g(x)} \approx_\delta S^x_g B^x_{g(x)}$.
   328	\end{lemma}
   329	\begin{proof}
   330		\leanok
   331		\uses{lem:distance-function-indexed-contraction}
   332		Expand the left-hand side and group the sum over $g$ according to the value $a = g(x)$:
   333		\[
   334			\E_x \sum_g \bigl\lVert S^x_g (A^x_{g(x)} - B^x_{g(x)})\, \ket{\psi} \bigr\rVert^2
   335			= \E_x \sum_a \bra{\psi} (A^x_a - B^x_a)^\dagger \Bigl( \sum_{g\,:\,g(x)=a} (S^x_g)^\dagger S^x_g \Bigr) (A^x_a - B^x_a) \ket{\psi}\,.
   336		\]
   337		% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:347-361) ends with
   338		% "at most delta by assumption"; under def:povm-distance the hypothesis only bounds this
   339		% quantity by O(delta), which is what the conclusion requires.
   340		Since $\sum_{g\,:\,g(x)=a} (S^x_g)^\dagger S^x_g \le \sum_g (S^x_g)^\dagger S^x_g \le \Id$, this is at most $\E_x \sum_a \lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2$, which is $O(\delta)$ by the hypothesis $A^x_a \approx_\delta B^x_a$ (Definition~\ref{def:povm-distance}); this is exactly the bound required for the conclusion.
   341	\end{proof}
   342	
   343	\begin{lemma}[Absorbing an approximating family into a projective sum]\label{lem:cool-closeness-fact}
   344		\lean{MIPStarRE.QPBT.opDistSq_sum_sub_mul_le_of_projective}
   345		\leanok
   346		\uses{def:povm-distance, def:povm-conventions}
   347		Let $\mathcal X$ and $\mathcal A$ be finite sets and $\mu$ a distribution on $\mathcal X$. Let $\{A^x_a\}_{a \in \mathcal A}$ be a projective measurement and let $\{B^x_a\}_{a \in \mathcal A}$ be a set of matrices. If $A^x_a \approx_\delta B^x_a$, then for all subsets $S \subseteq \mathcal A$ we have
   348		\[
   349			\sum_{a \in S} A^x_a \approx_\delta \sum_{a \in S} A^x_a \cdot B^x_a\,.
   350		\]
   351	\end{lemma}
   352	\begin{proof}
   353		\leanok
   354		\uses{lem:distance-projective-orthogonality,
   355			lem:distance-projective-sum}
   356		By projectivity, $\sum_{a \in S} (A^x_a - A^x_a B^x_a) = \sum_{a \in S} A^x_a (A^x_a - B^x_a)$. Expanding the squared norm of the corresponding vector, the cross terms for distinct $a \ne a' \in S$ vanish because $A^x_a A^x_{a'} = 0$, so
   357		\begin{align*}
   358			\E_x \Bigl\lVert \sum_{a \in S} \bigl(A^x_a - A^x_a B^x_a\bigr) \ket{\psi} \Bigr\rVert^2
   359			&= \E_x \sum_{a \in S} \bra{\psi} (A^x_a - B^x_a)^\dagger A^x_a (A^x_a - B^x_a) \ket{\psi}\\
   360			&\le \E_x \sum_a \lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2\,,
   361		\end{align*}
   362		% Under def:povm-distance the closeness hypothesis bounds the final quantity by
   363		% O(delta), not by delta itself; the source
   364		% (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:364-380) elides this.
   365		where the last step uses $A^x_a \le \Id$. All expectations are taken according to $\mu$, and the last quantity is $O(\delta)$ by the assumption $A^x_a \approx_\delta B^x_a$ (Definition~\ref{def:povm-distance}), which is the bound required for the conclusion.
   366	\end{proof}
   367	
   368	\begin{lemma}[Triangle inequality; Fact 4.28 in \cite{Natarajan2018NEEXP}]\label{fact:triangle}
   369		\lean{MIPStarRE.QPBT.opFamilyDistSq_le_of_le_of_le}
   370		\leanok
   371		\uses{def:povm-distance}
   372		If $A^x_a \approx_\delta B^x_a$ and $B^x_a \approx_{\eps} C^x_a$, then $A^x_a \approx_{\delta+\eps} C^x_a$.
   373	\end{lemma}
   374	\begin{proof}
   375		\leanok
   376		\uses{def:povm-distance}
   377		Stated in the source without proof; it is Fact 4.28 of \cite{Natarajan2018NEEXP}. For every $x$ and $a$, $\lVert (A^x_a - C^x_a)\ket{\psi} \rVert^2 \le 2\lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2 + 2\lVert (B^x_a - C^x_a)\ket{\psi} \rVert^2$. Averaging over $x$ and summing over $a$ gives the claim; the factor $2$ is absorbed by the $O(\cdot)$ in Definition~\ref{def:povm-distance}.
   378	\end{proof}
   379	
   380	\begin{lemma}[Triangle inequality for ``$\simeq$''; Proposition 4.29 in \cite{Ji2020LowIndividualDegree}]\label{fact:triangle-for-simeq}
   381		\lean{MIPStarRE.QPBT.consistencyDefect_trans_le}
   382		\leanok
   383		\uses{def:consistency}
   384		If $A^x_a \ot \Id_B \simeq_{\eps} \Id_A \ot B^x_a$, and $C^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$, and $C^x_a \ot \Id_B \simeq_\gamma \Id_A \ot D^x_a$, then
   385		\[
   386			A^x_a \ot \Id_B \simeq_{\eps + 2\sqrt{\delta+\gamma}} \Id_A \ot D^x_a\,.
   387		\]
   388	\end{lemma}
   389	\begin{proof}
   390		\leanok
   391		\uses{fact:agreement, fact:triangle, lem:distance-overlap-gap,
   392			lem:distance-defect-overlap, lem:distance-symmetry}
   393		Stated in the source without proof; it is Proposition 4.29 of \cite{Ji2020LowIndividualDegree}. The two hypotheses involving $C$ convert, via Lemma~\ref{fact:agreement}, into state-dependent closeness of $C^x_a \ot \Id_B$ to both $\Id_A \ot B^x_a$ and $\Id_A \ot D^x_a$, hence of $\Id_A \ot B^x_a$ to $\Id_A \ot D^x_a$ at cost $O(\delta+\gamma)$. The first consistency then transfers from $B$ to $D$ by expanding the off-diagonal mass and applying the Cauchy--Schwarz inequality, which turns the squared-distance bound into the term $2\sqrt{\delta+\gamma}$.
   394	\end{proof}
   395	
   396	\begin{lemma}[Data processing; Fact 4.26 in \cite{Natarajan2018NEEXP}]\label{fact:data-processing}
   397		\lean{MIPStarRE.QPBT.consistencyDefect_postprocess_le}
   398		\leanok
   399		\uses{def:consistency, def:bracket}
   400		Suppose $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$. Then for any function $f$ on the outcome set,
   401		\[
   402			A^x_{[f(\cdot)=b]} \ot \Id_B \simeq_\delta \Id_A \ot B^x_{[f(\cdot)=b]}\,.
   403		\]
   404	\end{lemma}
   405	\begin{proof}
   406		\leanok
   407		\uses{def:distance-state-quadratic-form,
   408			lem:distance-consistency-term, lem:distance-point-defect,
   409			def:distance-left-placed-measurement,
   410			def:distance-right-placed-measurement,
   411			lem:distance-placed-product-qform,
   412			lem:distance-postprocess-overlap}
   413		Stated in the source without proof; it is Fact 4.26 of \cite{Natarajan2018NEEXP}. Every off-diagonal pair $(b, b')$ with $b \ne b'$ of the post-processed families pulls back to pairs $(a, a')$ with $f(a) = b \ne b' = f(a')$, and in particular $a \ne a'$. Coarse-graining therefore only merges terms of the off-diagonal sum, so the post-processed off-diagonal mass is at most the original one.
   414	\end{proof}
